apiVersion: policy.karmada.io/v1alpha1
kind: PropagationPolicy
metadata: {name: api}
spec:
  resourceSelectors: [{apiVersion: apps/v1, kind: Deployment, name: api}]
  placement:
    clusterAffinity: {clusterNames: [prod-eu, prod-us]}
    replicaScheduling: {replicaSchedulingType: Divided}

apiVersion: argoproj.io/v1alpha1
kind: ApplicationSet
metadata: {name: api}
spec:
  generators: [{clusters: {selector: {matchLabels: {env: prod}}}}]
  template:
    metadata: {name: 'api-{{name}}'}
    spec:
      project: default
      source: {repoURL: https://git.example.com/apps.git, path: 'api/overlays/{{metadata.labels.region}}', targetRevision: main}
      destination: {server: '{{server}}', namespace: api}
      syncPolicy: {automated: {prune: true, selfHeal: true}}
